#include "timeout_f_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void timeout_f_timeout_func (Timeout timeout)
{
	#define TIMEOUT_F	((Timeout_F *)timeout)

	Exec_Q_Msg *exec_q_msg ; 

	remove_exec_q_msg :
	{
		exec_q_msg = exec_q_remove( timeout_exec_q_free );

		if( exec_q_msg )
		{
			exec_q_insert ( exec_q_msg , TIMEOUT_F->exec_func) ;
		}
		else
		{
			if( exec_q_free_add( timeout_exec_q_free , sizeof( Exec_Q_Msg) ) )
			{				
                goto remove_exec_q_msg ; 
			};
		};
	};

	#undef TIMEOUT_F
}

